from pathlib import Path
import json,html
R=Path(__file__).resolve().parent
rows=json.loads((R/'timeline.json').read_text())
subs=['以照片核对真实借走的物资','人工逐件清点，慢且容易漏看','模型建议与申请清单逐项对照','师生与管理员协同的共享工作台','同一笔申请包含喇叭与麦架','审批后才能进入交接拍照','真实推理：喇叭 ×1 · 麦架 ×1','照片、清单与识别建议同步留存','实际借出件数由管理员确认','库存变化与操作流水一并记录','三路模型互补，按框去重并计数','真实仓库照片标注与三段训练','训练照回查，不代表新场景准确率','在线体验 · 公开源代码']
chips=['PHOTO · VERIFY','PAIN POINT','WORKFLOW','PRODUCT','APPLICATION','APPROVAL','LIVE MODEL','EVIDENCE','HUMAN REVIEW','STOCK LEDGER','VISION ENGINE','TRAINING','EVALUATION','CLOSING']
parts=[];js=['window.__timelines = window.__timelines || {};','const tl = gsap.timeline({paused:true});']
for i,r in enumerate(rows):
 n=i+1;s=r['start'];dur=r['duration'];img=r['image'];image=f'assets/{"recognition-eval.jpg" if n==13 else ("scene-end.jpg" if n==14 else img)}'
 if n in (1,14):
  links='<div class="end-link">blog.oppenheimer123.xyz/warehouse-ai/</div><div class="end-link small">github.com/Feynman724/warehouse-ai</div>' if n==14 else '<div class="pills"><span>同框拍照</span><span>物资识别</span><span>库存留痕</span></div>'
  content=f'<div class="hero"><div class="hero-copy"><div class="eyebrow">{chips[i]}</div><h1 id="t{n}">{html.escape(r["title"])}</h1><p id="d{n}">{subs[i]}</p>{links}</div><div class="cover-photo"><img class="shot" src="{image}"></div></div>'
 else:
  if img.endswith('.png'):
   visual=f'<div class="browser"><div class="browser-bar"><i></i><i></i><i></i><span>校学生会物资仓库 AI 借还工作台</span></div><div class="browser-view"><img class="shot" src="{image}"></div></div>'
  else:visual=f'<div class="photo-card"><img class="shot" src="{image}"></div>'
  content=f'<div class="scene-content"><header><div class="eyebrow">{chips[i]} · {n:02d}</div><h1 id="t{n}">{html.escape(r["title"])}</h1></header><div class="main-row">{visual}<aside><div class="rail-num">{n:02d}</div><div class="rail-rule"></div><p id="d{n}">{subs[i]}</p><div class="rail-extra">真实产品 · 真实照片 · 可追溯记录</div></aside></div></div>'
 parts.append(f'<section id="scene-{n}" class="clip scene {"last" if n==14 else ""}" data-start="{s}" data-duration="{dur}" data-track-index="{n}"><div class="paper-grid"></div>{content}<div class="lower"><span>{r["tag"]}</span><div class="progress"><b style="width:{n/14*100:.1f}%"></b></div><span>{n:02d} / 14</span></div></section>')
 parts.append(f'<audio id="voice-{n}" data-start="{s+0.6:.3f}" data-duration="{r["voice_duration"]:.3f}" data-track-index="{50+n}" src="{r["audio"]}" data-volume="1"></audio>')
 js.extend([f'tl.from("#scene-{n}",{{x:90,opacity:0,duration:0.48,ease:"power2.out"}},{s});',f'tl.from("#t{n}",{{y:34,opacity:0,duration:0.72,ease:"power3.out"}},{s+0.20:.3f});',f'tl.from("#d{n}",{{x:25,opacity:0,duration:0.62,ease:"expo.out"}},{s+0.48:.3f});',f'tl.from("#scene-{n} .eyebrow",{{opacity:0,y:16,duration:0.42,ease:"sine.out"}},{s+0.12:.3f});',f'tl.from("#scene-{n} .main-row, #scene-{n} .cover-photo",{{opacity:0,scale:0.97,duration:0.68,ease:"power1.out"}},{s+0.36:.3f});',f'tl.to("#scene-{n} .shot",{{scale:1.035,duration:{max(dur-1,1):.3f},ease:"none"}},{s+0.8:.3f});'])
js.append('window.__timelines["main"] = tl;')
css='''@font-face{font-family:"PingFang SC";src:local("PingFang SC")}@font-face{font-family:"Avenir Next";src:local("Avenir Next")}*{box-sizing:border-box}html,body{margin:0;width:1920px;height:1080px;overflow:hidden;background:#F5F3ED;color:#1F2924;font-family:"PingFang SC",sans-serif}#root{position:relative;width:1920px;height:1080px;overflow:hidden}.scene{position:absolute;inset:0;background:#F5F3ED;overflow:hidden;z-index:1}.paper-grid{position:absolute;inset:0;background-image:linear-gradient(rgba(23,76,58,.05) 1px,transparent 1px),linear-gradient(90deg,rgba(23,76,58,.05) 1px,transparent 1px);background-size:120px 120px;opacity:.35;pointer-events:none}#root:after{content:"浙江大学 · 智创校园";position:absolute;top:52px;left:150px;z-index:100;color:#174C3A;font-size:20px;font-weight:700}.corner-logo{position:absolute;top:40px;left:90px;display:flex;align-items:center;gap:14px;z-index:3;color:#174C3A;font-size:20px;font-weight:700}.corner-logo img{width:48px;height:48px;object-fit:contain}.lower{position:absolute;bottom:42px;left:90px;right:90px;z-index:3;display:flex;align-items:center;gap:28px;color:#174C3A;font-family:"Avenir Next","PingFang SC",sans-serif;font-size:18px;font-weight:700;letter-spacing:.08em}.lower .progress{height:3px;flex:1;background:#DCE9E2}.lower .progress b{height:100%;display:block;background:#174C3A}.scene-content{position:relative;width:100%;height:100%;padding:130px 90px 100px;display:flex;flex-direction:column;gap:28px}.scene-content header{min-height:135px}.eyebrow{font-family:"Avenir Next","PingFang SC",sans-serif;color:#23664F;font-size:21px;font-weight:800;letter-spacing:.1em}.scene-content h1{font-size:66px;line-height:1.14;letter-spacing:-.04em;margin:12px 0 0;max-width:1680px;font-weight:800}.main-row{display:flex;gap:45px;min-height:0;flex:1}.browser{width:1390px;height:100%;background:#FFFEFA;border:1px solid #D9DED9;border-radius:25px;box-shadow:0 26px 70px rgba(24,43,35,.13);padding:16px 16px 18px;overflow:hidden}.browser-bar{height:42px;display:flex;align-items:center;gap:9px;padding-left:12px;color:#58655D;font-size:15px}.browser-bar i{display:block;width:12px;height:12px;background:#DCE9E2;border-radius:50%}.browser-bar span{margin-left:auto;margin-right:auto}.browser-view{height:calc(100% - 42px);border-radius:12px;overflow:hidden}.browser-view img{display:block;width:100%;height:100%;object-fit:cover;object-position:top center;transform-origin:50% 35%}.photo-card{width:1180px;height:100%;display:flex;align-items:center;justify-content:center;background:#FFFEFA;border:1px solid #D9DED9;border-radius:25px;box-shadow:0 26px 70px rgba(24,43,35,.13);overflow:hidden;padding:25px}.photo-card img{height:100%;max-width:100%;object-fit:contain;transform-origin:center}.main-row aside{flex:1;display:flex;flex-direction:column;justify-content:center;min-width:0;padding:20px 0}.rail-num{font-family:"Avenir Next",sans-serif;font-size:138px;line-height:1;color:#174C3A;font-weight:800;letter-spacing:-.07em}.rail-rule{width:72px;height:5px;background:#C79648;margin:32px 0}.main-row aside p{font-size:39px;line-height:1.4;font-weight:700;margin:0;color:#1F2924}.rail-extra{font-size:20px;color:#58655D;margin-top:38px}.hero{position:relative;width:100%;height:100%;padding:160px 90px 125px;display:flex;align-items:center;gap:80px}.hero-copy{width:975px;z-index:2;display:flex;flex-direction:column;gap:35px}.hero-copy h1{font-size:112px;line-height:1.08;letter-spacing:-.055em;color:#174C3A;margin:0;font-weight:800}.hero-copy p{font-size:40px;line-height:1.45;margin:0;font-weight:650}.cover-photo{height:760px;flex:1;border-radius:30px;background:#FFFEFA;overflow:hidden;box-shadow:0 30px 80px rgba(24,43,35,.15)}.cover-photo img{width:100%;height:100%;object-fit:cover;object-position:center;transform-origin:center}.pills{display:flex;gap:14px}.pills span{padding:12px 22px;border-radius:50px;background:#DCE9E2;color:#174C3A;font-size:23px;font-weight:700}.end-link{font-size:30px;color:#174C3A;font-weight:700}.end-link.small{font-size:25px;margin-top:-20px}.last .hero-copy{width:1080px}.last .hero-copy h1{font-size:88px}.last .cover-photo{height:670px}'''
last=rows[-1]['start']+rows[-1]['duration']
(R/'index.html').write_text('<!doctype html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=1920,height=1080"><script src="https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js"></script><style>'+css+'</style></head><body><div id="root" data-composition-id="main" data-start="0" data-duration="'+f'{last:.3f}'+'" data-width="1920" data-height="1080">'+'\n'.join(parts)+'</div><script>'+'\n'.join(js)+'</script></body></html>',encoding='utf8')
print('wrote',len(rows),'scenes',round(last,1),'seconds')
